import { Component, computed, signal } from '@angular/core';

@Component({
  selector: 'app-user-card',
  template: `
    <article class="card">
      <h2>{{ name() }}</h2>
      <p>{{ initials() }} · joined {{ year }}</p>
      <button (click)="toggle()">{{ expanded() ? 'Less' : 'More' }}</button>
    </article>
  `,
  styles: `
    .card { border: 1px solid #ccc; padding: 1rem; border-radius: 8px; }
    h2 { margin: 0 0 0.5rem; }
  `,
})
export class UserCard {
  readonly name = signal('Ada Lovelace');
  readonly year = 2024;
  readonly expanded = signal(false);

  readonly initials = computed(() =>
    this.name()
      .split(' ')
      .map((part) => part[0])
      .join(''),
  );

  toggle(): void {
    this.expanded.update((open) => !open);
  }
}

import { Component, signal } from '@angular/core';

type Status = 'pending' | 'shipped' | 'cancelled';

@Component({
  selector: 'app-order-status',
  template: `
    @if (status() === 'shipped') {
      <p>Your order is on its way.</p>
    } @else if (status() === 'cancelled') {
      <p>This order was cancelled.</p>
    } @else {
      <p>We are preparing your order.</p>
    }
    <button (click)="ship()">Mark as shipped</button>
  `,
})
export class OrderStatus {
  readonly status = signal<Status>('pending');

  ship(): void {
    this.status.set('shipped');
  }
}

