import { Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { AbstractControl, FormBuilder, ReactiveFormsModule, ValidationErrors, Validators } from '@angular/forms';

function noSpaces(control: AbstractControl<string>): ValidationErrors | null {
  return control.value.includes(' ') ? { spaces: true } : null;
}

@Component({
  selector: 'app-signup',
  imports: [ReactiveFormsModule],
  templateUrl: './signup.html',
})
export class Signup {
  private readonly fb = inject(FormBuilder);

  readonly form = this.fb.nonNullable.group({
    username: ['', [Validators.required, Validators.minLength(3), noSpaces]],
    email: ['', [Validators.required, Validators.email]],
    newsletter: [false],
  });

  private readonly username = toSignal(this.form.controls.username.valueChanges, { initialValue: '' });
  readonly remaining = computed(() => 20 - this.username().length);

  submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    console.log('submitted', this.form.getRawValue());
    this.form.reset();
  }
}

